describe('Product Search by Keyword - Instant Results', () => {
  beforeEach(() => {
    cy.visit('/products');
  });

  it('should display instant search results when user enters a keyword', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/products/search*').as('searchResults');

    // Get the search input element
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').type('laptop');

    // Verify the search input has focus
    cy.get('[data-testid="search-input"]').should('have.focus');

    // Wait for the API call to complete
    cy.wait('@searchResults');

    // Verify search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="search-results"]').should('contain', 'laptop');

    // Verify results are listed
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify the first result is displayed
    cy.get('[data-testid="search-result-item"]').first().should('be.visible');

    // Verify the search results are sorted alphabetically
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'Apple MacBook Pro');
    cy.get('[data-testid="search-result-item"]').last().should('contain', 'Lenovo ThinkPad');
  });

  it('should handle empty search input and display no results message', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/products/search*').as('searchResults');

    // Get the search input element
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Clear the search input
    cy.get('[data-testid="search-input"]').clear();

    // Verify the search input is empty
    cy.get('[data-testid="search-input"]').should('have.value', '');

    // Wait for the API call to complete
    cy.wait('@searchResults');

    // Verify no results are displayed
    cy.get('[data-testid="search-results"]').should('not.exist');

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No products found');
  });
});
